// This file is generated by AI.

// 引擎目录校验与自述文件读取 (会访问磁盘, 因此与纯逻辑分开放)。

import { ENGINE_MANIFEST_FILES, hasManifestInfo, parseEngineManifest, type EngineManifestInfo } from './engine';
import { fs } from './fs';
import { baseName, joinPath } from './paths';

export interface EngineValidation {
  valid: boolean;
  name: string;
  version?: string;
  manifestId?: string;
  error?: string;
}

/**
 * 校验一个目录是不是可用的 WebGAL 引擎。
 *
 * 判据只有一条硬性的: 目录里得有 `index.html` —— 引擎在预览里是作为静态站点挂载的,
 * 没有它就没有任何意义。自述文件是可选的: 老的发行包与自建引擎可能没有, 那时只是
 * 显示名退回目录名、版本显示"未知"。
 */
export async function validateEngine(path: string): Promise<EngineValidation> {
  const name = baseName(path);
  try {
    const stat = await fs.exists(path);
    if (!stat.exists || !stat.isDirectory) return { valid: false, name, error: '目录不存在' };

    const index = await fs.exists(joinPath(path, 'index.html'));
    if (!index.exists || index.isDirectory) {
      return { valid: false, name, error: '不是 WebGAL 引擎目录 (缺少 index.html)' };
    }

    const info = await readEngineManifest(path);
    return {
      valid: true,
      name: info?.name ?? name,
      version: info?.version,
      manifestId: info?.manifestId,
    };
  } catch (error) {
    return { valid: false, name, error: String(error) };
  }
}

/**
 * 读取引擎自述文件 (`webgal-engine.json` 优先, 退回 `package.json`)。
 *
 * 文件缺失或解析失败都返回 null, 而不是抛错 —— 探测版本是"锦上添花", 不该让
 * 添加引擎这件事失败。
 */
export async function readEngineManifest(path: string): Promise<EngineManifestInfo | null> {
  for (const file of ENGINE_MANIFEST_FILES) {
    const filePath = joinPath(path, file);
    const exists = await fs.exists(filePath);
    if (!exists.exists || exists.isDirectory) continue;
    try {
      const info = parseEngineManifest(JSON.parse(await fs.readText(filePath)));
      if (hasManifestInfo(info)) return info;
    } catch {
      // 自述文件坏掉时继续尝试下一个
    }
  }
  return null;
}
